import { addStreets } from './roads.js';

// Roads, sidewalks, and the pedestrian collision contract live here.
// District agents do not edit this file. The infrastructure agent does.
export async function register(ctx) {
  const stats = addStreets(ctx.world, ctx.maps, ctx.terrain, ctx.features);
  ctx.shared.roads = stats;
  if (ctx.extension) {
    const extension = await import(/* @vite-ignore */ new URL(ctx.extension, import.meta.url).href);
    if (typeof extension.register === 'function') await extension.register(ctx);
  }
}
